// Word frequency: words are maximal runs of ASCII letters, lowercased.
// Prints the 10 most common as "word count", ties broken by word.
// Fast path: words of up to 8 letters are packed (lowercased) into a uint64
// key found with SWAR on 8-byte loads; longer words go to a string table.
// Assumes a little-endian machine (arm64 / x86-64).
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/mman.h>

#define HI 0x8080808080808080ULL
#define MULC 0x9E3779B97F4A7C15ULL

typedef struct { uint64_t key, n; } SE;
static SE *stab; static size_t scap, sused; static unsigned sshift;

typedef struct { unsigned char *p; size_t len; uint32_t hash; uint64_t n; } LE;
static LE *ltab; static size_t lcap, lused;

static unsigned char isl[256];

static void die(const char *m) { perror(m); exit(1); }

static void sgrow(void) {
    size_t ncap = scap * 2; unsigned nshift = sshift - 1;
    SE *nt = calloc(ncap, sizeof(SE));
    if (!nt) die("calloc");
    for (size_t i = 0; i < scap; i++) if (stab[i].key) {
        size_t j = (size_t)((stab[i].key * MULC) >> nshift);
        while (nt[j].key) j = (j + 1) & (ncap - 1);
        nt[j] = stab[i];
    }
    free(stab); stab = nt; scap = ncap; sshift = nshift;
}

static inline void sadd(uint64_t key) {
    size_t j = (size_t)((key * MULC) >> sshift);
    for (;;) {
        SE *e = &stab[j];
        if (e->key == key) { e->n++; return; }
        if (!e->key) {
            e->key = key; e->n = 1;
            if (++sused * 2 > scap) sgrow();
            return;
        }
        j = (j + 1) & (scap - 1);
    }
}

static void lgrow(void) {
    size_t ncap = lcap * 2;
    LE *nt = calloc(ncap, sizeof(LE));
    if (!nt) die("calloc");
    for (size_t i = 0; i < lcap; i++) if (ltab[i].p) {
        size_t j = ltab[i].hash & (ncap - 1);
        while (nt[j].p) j = (j + 1) & (ncap - 1);
        nt[j] = ltab[i];
    }
    free(ltab); ltab = nt; lcap = ncap;
}

// s[0..len) are all letters (any case), len > 8.
static void ladd(const unsigned char *s, size_t len) {
    uint32_t h = 2166136261u;
    for (size_t i = 0; i < len; i++) h = (h ^ (uint32_t)(s[i] | 0x20)) * 16777619u;
    h ^= h >> 15;
    size_t j = h & (lcap - 1);
    for (;;) {
        LE *e = &ltab[j];
        if (!e->p) {
            unsigned char *c = malloc(len);
            if (!c) die("malloc");
            for (size_t i = 0; i < len; i++) c[i] = s[i] | 0x20;
            e->p = c; e->len = len; e->hash = h; e->n = 1;
            if (++lused * 2 > lcap) lgrow();
            return;
        }
        if (e->hash == h && e->len == len) {
            size_t i = 0;
            while (i < len && e->p[i] == (unsigned char)(s[i] | 0x20)) i++;
            if (i == len) { e->n++; return; }
        }
        j = (j + 1) & (lcap - 1);
    }
}

// p points at a letter; consumes the whole word, returns pointer past it.
static const unsigned char *scalar_word(const unsigned char *p, const unsigned char *end) {
    const unsigned char *s = p;
    while (p < end && isl[*p]) p++;
    size_t len = (size_t)(p - s);
    if (len <= 8) {
        uint64_t key = 0;
        for (size_t i = 0; i < len; i++) key |= (uint64_t)(s[i] | 0x20) << (8 * i);
        sadd(key);
    } else ladd(s, len);
    return p;
}

// 0x80 in every byte of w that is an ASCII letter.
static inline uint64_t letmask(uint64_t w) {
    uint64_t t = (w | 0x2020202020202020ULL) & 0x7f7f7f7f7f7f7f7fULL;
    uint64_t ge = t + 0x1f1f1f1f1f1f1f1fULL;   // bit7 set iff t >= 'a'
    uint64_t gt = t + 0x0505050505050505ULL;   // bit7 set iff t >  'z'
    return ge & ~gt & ~w & HI;
}

typedef struct { const unsigned char *p; size_t len; uint64_t n; } Out;

static int cmp(const void *a, const void *b) {
    const Out *x = a, *y = b;
    if (x->n != y->n) return x->n > y->n ? -1 : 1;
    size_t m = x->len < y->len ? x->len : y->len;
    int c = memcmp(x->p, y->p, m);
    if (c) return c;
    return (x->len > y->len) - (x->len < y->len);
}

int main(void) {
    const unsigned char *buf = NULL; size_t len = 0;
    struct stat sb;
#ifndef NOMMAP
    if (fstat(0, &sb) == 0 && S_ISREG(sb.st_mode) && sb.st_size > 0 && lseek(0, 0, SEEK_CUR) == 0) {
        void *m = mmap(NULL, (size_t)sb.st_size, PROT_READ, MAP_PRIVATE, 0, 0);
        if (m != MAP_FAILED) { buf = m; len = (size_t)sb.st_size; }
    }
#endif
    if (!buf) {
        size_t bcap = 1 << 16;
        if (fstat(0, &sb) == 0 && S_ISREG(sb.st_mode) && sb.st_size > 0) bcap = (size_t)sb.st_size + 1;
        unsigned char *b = malloc(bcap);
        if (!b) die("malloc");
        for (;;) {
            if (len == bcap) { bcap *= 2; b = realloc(b, bcap); if (!b) die("realloc"); }
            ssize_t r = read(0, b + len, bcap - len);
            if (r < 0) die("read");
            if (r == 0) break;
            len += (size_t)r;
        }
        buf = b;
    }
    for (int c = 0; c < 26; c++) { isl['a' + c] = 1; isl['A' + c] = 1; }
    scap = 1 << 14; sshift = 64 - 14; stab = calloc(scap, sizeof(SE));
    lcap = 1 << 12; ltab = calloc(lcap, sizeof(LE));
    if (!stab || !ltab) die("calloc");

    const unsigned char *p = buf, *end = buf + len;
    while (p + 8 <= end) {
        uint64_t w; memcpy(&w, p, 8);
        uint64_t L = letmask(w);
        if (!L) { p += 8; continue; }
        unsigned skip = (unsigned)__builtin_ctzll(L) >> 3;
        if (skip) {
            p += skip;
            if (p + 8 > end) break;
            memcpy(&w, p, 8);
            L = letmask(w);
        }
        uint64_t N = L ^ HI;                 // 0x80 in every non-letter byte
        if (!N) { p = scalar_word(p, end); continue; }
        unsigned wl = (unsigned)__builtin_ctzll(N) >> 3;   // 1..7
        uint64_t key = (w | 0x2020202020202020ULL) & (~0ULL >> (64 - 8 * wl));
        sadd(key);
        p += wl + 1;                         // p[wl] is known to be a non-letter
    }
    while (p < end) { if (isl[*p]) p = scalar_word(p, end); else p++; }

    size_t total = sused + lused, k = 0;
    Out *out = malloc((total + 1) * sizeof(Out));
    unsigned char *arena = malloc(sused * 8 + 8);
    if (!out || !arena) die("malloc");
    unsigned char *a = arena;
    for (size_t i = 0; i < scap; i++) if (stab[i].key) {
        uint64_t key = stab[i].key; size_t n = 0;
        while (n < 8 && ((key >> (8 * n)) & 0xff)) { a[n] = (unsigned char)(key >> (8 * n)); n++; }
        out[k].p = a; out[k].len = n; out[k].n = stab[i].n; k++;
        a += 8;
    }
    for (size_t i = 0; i < lcap; i++) if (ltab[i].p) {
        out[k].p = ltab[i].p; out[k].len = ltab[i].len; out[k].n = ltab[i].n; k++;
    }
    qsort(out, k, sizeof(Out), cmp);
    for (size_t i = 0; i < k && i < 10; i++) {
        fwrite(out[i].p, 1, out[i].len, stdout);
        printf(" %llu\n", (unsigned long long)out[i].n);
    }
    return 0;
}
